import { ref, onMounted, onBeforeUnmount, computed } from 'vue';
import DockerContainers from '@/components/Container/DockerContainers.vue'; // 修改为你的实际路径
import axios from 'axios';
import * as echarts from 'echarts';

// refs

export default {
  __name: 'MonitorView',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const dockerContainersRef = ref(null);
    const containers = ref([]); // 容器列表
    const AContainers = ref([]); // 容器列表
    const selectedContainer = ref(''); // 当前选中的容器
    const bandwidthChartRef = ref(null);
    const networkChartRef = ref(null);
    const bandwidthRxData = ref([]);
    const bandwidthTxData = ref([]);
    let bandwidthChart = null;
    let networkChart = null;

    // 图表数据
    const timeData = ref([]);
    const bandwidthData = ref([]);
    const rxData = ref([]);
    const txData = ref([]);
    const containersIntervalId = ref(null); // 新增专用容器刷新定时器
    const statsIntervalId = ref(null); // 新增统计定时器

    // 修改获取容器逻辑
    const fetchContainers = async () => {
      try {
        if (!dockerContainersRef.value) return;

        // 强制等待子组件数据刷新
        await dockerContainersRef.value.fetchContainers();

        // 使用解构保持响应性
        containers.value = [...dockerContainersRef.value.containers];

        // 如果当前选中的容器已不存在，清空选择
        if (!containers.value.some(c => formatContainerName(c.name) === selectedContainer.value)) {
          selectedContainer.value = '';
        }
      } catch (error) {
        console.error('容器列表刷新失败:', error);
      }
    };

    // 开始监控
    const startMonitoring = () => {
      // 清除旧定时器
      if (statsIntervalId.value) {
        clearInterval(statsIntervalId.value);
      }

      // 重置数据时需要保留最后几个点保证图表连续性
      if (timeData.value.length > 0) {
        const keepCount = 5;
        timeData.value = timeData.value.slice(-keepCount);
        bandwidthRxData.value = bandwidthRxData.value.slice(-keepCount);
        bandwidthTxData.value = bandwidthTxData.value.slice(-keepCount);
        rxData.value = rxData.value.slice(-keepCount);
        txData.value = txData.value.slice(-keepCount);
      }
      statsIntervalId.value = setInterval(async () => {
        if (!selectedContainer.value) return;
        const timestamp = new Date().toLocaleTimeString();
        try {
          const bandwidthRes = await axios.get(`http://localhost:8081/stats/bandwidth/${selectedContainer.value}?interval=1000`);
          const statsRes = await axios.get(`http://localhost:8081/stats/networkStats/${selectedContainer.value}`);
          timeData.value.push(timestamp);
          bandwidthRxData.value.push(bandwidthRes.data.rxBytesPerSec);
          bandwidthTxData.value.push(bandwidthRes.data.txBytesPerSec);
          rxData.value.push(statsRes.data.rxBytes);
          txData.value.push(statsRes.data.txBytes);
          if (timeData.value.length > 20) {
            timeData.value.shift();
            bandwidthData.value.shift();
            rxData.value.shift();
            txData.value.shift();
          }
          updateCharts();
        } catch (err) {
          console.error('监控数据获取失败', err);
        }
      }, 1000);
    };

    // 更新图表
    // 修改图表更新逻辑
    const updateCharts = () => {
      // 初始化图表
      if (!bandwidthChart && bandwidthChartRef.value) {
        bandwidthChart = echarts.init(bandwidthChartRef.value);
      }
      if (!networkChart && networkChartRef.value) {
        networkChart = echarts.init(networkChartRef.value);
      }

      // 更新选项
      const commonOptions = {
        animation: false,
        // 关闭动画提升性能
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            animation: false // 关闭指示器动画
          }
        }
      };
      bandwidthChart?.setOption({
        ...commonOptions,
        title: {
          text: '容器带宽使用率 (Bytes/s)'
        },
        xAxis: {
          data: timeData.value
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          data: bandwidthRxData.value
        }, {
          data: bandwidthTxData.value
        }]
      });
      networkChart?.setOption({
        ...commonOptions,
        title: {
          text: '网络收发字节数 (累计)'
        },
        xAxis: {
          data: timeData.value
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          data: rxData.value
        }, {
          data: txData.value
        }]
      });
    };

    // 计算可用的运行中容器
    const availableContainers = computed(() => {
      return containers.value.filter(c => c.status?.includes('Up'));
    });
    const formatContainerName = name => {
      return name.replace(/^\//, '');
    };
    const formatStatus = status => {
      return status?.includes('Up') ? '运行中' : '已停止';
    };

    // 修改生命周期钩子
    onMounted(() => {
      containersIntervalId.value = setInterval(fetchContainers, 2000); // 改为2秒刷新
      fetchContainers(); // 立即执行一次
      AContainers.value = availableContainers;
    });
    onBeforeUnmount(() => {
      clearInterval(containersIntervalId.value);
      clearInterval(statsIntervalId.value);

      // 销毁图表实例
      if (bandwidthChart) {
        bandwidthChart.dispose();
        bandwidthChart = null;
      }
      if (networkChart) {
        networkChart.dispose();
        networkChart = null;
      }
    });
    const __returned__ = {
      dockerContainersRef,
      containers,
      AContainers,
      selectedContainer,
      bandwidthChartRef,
      networkChartRef,
      bandwidthRxData,
      bandwidthTxData,
      get bandwidthChart() {
        return bandwidthChart;
      },
      set bandwidthChart(v) {
        bandwidthChart = v;
      },
      get networkChart() {
        return networkChart;
      },
      set networkChart(v) {
        networkChart = v;
      },
      timeData,
      bandwidthData,
      rxData,
      txData,
      containersIntervalId,
      statsIntervalId,
      fetchContainers,
      startMonitoring,
      updateCharts,
      availableContainers,
      formatContainerName,
      formatStatus,
      ref,
      onMounted,
      onBeforeUnmount,
      computed,
      DockerContainers,
      get axios() {
        return axios;
      },
      get echarts() {
        return echarts;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
